// ingestCounter is the Counter-returning form of the shared parse loop.
func ingestCounter(in io.Reader, name string, counter *rollup.Counter, stderr io.Writer) (*rollup.Counter, int) {
	if code := streamSamples(in, name, counter, stderr); code != 0 {
		return nil, code
